/* eslint-disable no-console -- The local validation runner reports its bounded result. */
import { spawnSync } from 'node:child_process'
import { mkdirSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const workspace = resolve(import.meta.dirname, '../..')
const source = spawnSync(
  process.execPath,
  [resolve(workspace, 'scripts/ai-production-hardening/source-closure.mjs')],
  { cwd: workspace, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }
)
const closure = JSON.parse(source.stdout)
const bound = closure.repositories.filter(
  (repository) => repository.role === 'bound'
)
if (
  source.error ||
  ![0, 2].includes(source.status) ||
  closure.kind !== 'zx.ai.production.source-closure.v1' ||
  !/^sha256:[a-f0-9]{64}$/.test(closure.fingerprint) ||
  bound.some((repository) => !/^[a-f0-9]{40}$/.test(repository.commit ?? '')) ||
  (source.status === 2 &&
    !bound.some((repository) => repository.clean === false))
) {
  throw new Error('local-authority-source-closure-invalid')
}

// Local tests accept recorded working changes. The release runner still
// requires its original clean commit set; this result is never release evidence.
const result = spawnSync(
  process.execPath,
  [
    resolve(
      workspace,
      'scripts/ai-production-hardening/workbench-authority-observation.mjs'
    ),
    closure.fingerprint,
  ],
  {
    cwd: workspace,
    encoding: 'utf8',
    timeout: 300_000,
    maxBuffer: 64 * 1024 * 1024,
  }
)
const observation = JSON.parse(result.stdout)
if (result.error || result.status !== 0 || observation.valid !== true) {
  process.stderr.write(result.stderr)
  throw new Error('local-authority-observation-failed')
}
const evidence = process.env.ZXUI_VALIDATION_EVIDENCE_DIR
if (evidence) {
  mkdirSync(evidence, { recursive: true })
  writeFileSync(resolve(evidence, 'source-closure.json'), source.stdout)
  writeFileSync(resolve(evidence, 'authority-observation.json'), result.stdout)
}
console.log(
  JSON.stringify({
    scope: 'local-working-source-validation',
    sourceClosureFingerprint: closure.fingerprint,
    rootClean: closure.root.clean,
    personas: observation.personas,
    stages: observation.stages.length,
    valid: observation.valid,
  })
)

/* eslint-disable vue/one-component-per-file -- This harness creates independent owner/portal fixture components. */
import { defineComponent, h, reactive, ref, withDirectives } from 'vue'
import { useThemeCssAdapter } from '@zxio/theme-consumer/vue'
import { ZxThemeProvider } from '@zxio/zxui/theme-provider'
import { Widget as AcmeWidget } from '@acme/widget/vue'
import { Widget as ExamplePanel } from '@example/panel/vue'

// Deliberately invalid public consumer used only by the executable conformance runner.
const FailureProbe = defineComponent({
  props: { failure: String },
  setup(props) {
    const root = ref<HTMLElement | null>(null)
    const binding = useThemeCssAdapter(root, {
      id: 'acme-widget-css',
      actualVersion: props.failure === 'version' ? '9.0.0' : '1.0.0',
    })
    return () =>
      withDirectives(
        h('div', {
          ref: root,
          'data-failure-probe': binding.state.value,
          'data-probe-diagnostics': JSON.stringify(binding.diagnostics.value),
          style:
            props.failure === 'inline' ? { '--acme-widget-bg': 'red' } : {},
        }),
        [[binding.directive]]
      )
  },
})

export function createConsumerDemo(initial: Record<string, unknown> = {}) {
  const state = reactive({
    themeId: 'default',
    mode: 'light',
    density: 'default',
    contrast: 'normal',
    motion: 'full',
    radius: 'default',
    requestOverride: undefined as Record<string, unknown> | undefined,
    failureProbe: '',
    customPortal: false,
    disabled: false,
    nestedDisabled: false,
    show: true,
    instances: 1,
    seeds: undefined as unknown,
    overrides: undefined as unknown,
    ...initial,
  })
  const Root = defineComponent({
    setup() {
      return () =>
        h('div', { class: 'consumer-demo' }, [
          h('header', [
            h('h1', '周边库主题消费协议'),
            h('p', '业务只登记扩展。两个库通过最近 Provider 自动消费主题。'),
            ...Object.entries({
              themeId: ['default', 'defense-green'],
              mode: ['light', 'dark'],
              density: ['default', 'compact', 'comfortable'],
              contrast: ['normal', 'high', 'forced-colors'],
              motion: ['full', 'reduced', 'none'],
              radius: ['default', 'sharp', 'rounded'],
            }).map(([key, choices]) =>
              h('label', [
                `${key} `,
                h(
                  'select',
                  {
                    value: state[key as keyof typeof state],
                    onChange: (event: Event) => {
                      ;(state as Record<string, unknown>)[key] = (
                        event.target as HTMLSelectElement
                      ).value
                    },
                  },
                  choices.map((value) => h('option', { value }, value))
                ),
              ])
            ),
          ]),
          h('nav', [
            h('label', [
              h('input', {
                type: 'checkbox',
                checked: state.disabled,
                onChange: (event: Event) => {
                  state.disabled = (event.target as HTMLInputElement).checked
                },
              }),
              '停用 Widget 模块',
            ]),
            h('label', [
              h('input', {
                type: 'checkbox',
                checked: state.nestedDisabled,
                onChange: (event: Event) => {
                  state.nestedDisabled = (
                    event.target as HTMLInputElement
                  ).checked
                },
              }),
              '嵌套 Widget inactive',
            ]),
            h('label', [
              h('input', {
                type: 'checkbox',
                checked: Boolean(state.seeds),
                onChange: (event: Event) => {
                  state.seeds = (event.target as HTMLInputElement).checked
                    ? { brand: [0.42, 0.15, 0.56] }
                    : undefined
                },
              }),
              '品牌 Seeds',
            ]),
            h('label', [
              h('input', {
                type: 'checkbox',
                checked: Boolean(state.overrides),
                onChange: (event: Event) => {
                  state.overrides = (event.target as HTMLInputElement).checked
                    ? {
                        'acme-widget/gap': {
                          kind: 'literal',
                          value: { kind: 'value', value: 19, unit: 'px' },
                        },
                      }
                    : undefined
                },
              }),
              '库间距覆盖',
            ]),
          ]),
          h(
            ZxThemeProvider,
            {
              class: 'provider-root',
              ...(state.customPortal
                ? {
                    portalTarget: () =>
                      document.querySelector<HTMLElement>(
                        '[data-zx-consumer-destination="aux"]'
                      )!,
                  }
                : {}),
              themeId: state.themeId,
              mode: state.mode,
              density: state.density,
              contrast: state.contrast,
              motion: state.motion,
              radius: state.radius,
              ...state.requestOverride,
              composition: {
                ...(state.disabled ? { modules: ['example-panel'] } : {}),
                ...(state.seeds ? { seeds: state.seeds } : {}),
                ...(state.overrides ? { overrides: state.overrides } : {}),
              },
            } as never,
            () =>
              state.show
                ? [
                    state.failureProbe
                      ? h(FailureProbe, {
                          key: state.failureProbe,
                          failure: state.failureProbe,
                        })
                      : null,
                    ...Array.from({ length: state.instances }, (_, i) => [
                      h(AcmeWidget, { key: `a-${i}`, label: `outer-a-${i}` }),
                      h(ExamplePanel, { key: `b-${i}`, label: `outer-b-${i}` }),
                    ]),
                    h(
                      ZxThemeProvider,
                      {
                        class: 'provider-root',
                        scopeKey: 'nested',
                        mode: 'dark',
                        density: 'compact',
                        composition: state.nestedDisabled
                          ? { modules: ['example-panel'] }
                          : undefined,
                      },
                      () => [
                        h(AcmeWidget, { label: 'nested-a' }),
                        h(ExamplePanel, { label: 'nested-b' }),
                      ]
                    ),
                  ]
                : []
          ),
        ])
    },
  })
  return { Root, state }
}

/* eslint-disable no-console -- The isolated browser fixture emits verification diagnostics. */
import { createApp, createSSRApp, nextTick } from 'vue'
import { createDefaultBrowserThemeHost } from '@zxio/zxui/theme-host'
import { createThemeAssetResolver, success } from '@zxio/zxui/theme-runtime'
import { Widget as StandaloneWidget } from '@acme/widget/vue'
import data from 'virtual:consumer-fixture'
import { createConsumerDemo } from './app'
import '@acme/widget/style.css'
import '@example/panel/style.css'

const browser = window as any
const initial = browser.__CONSUMER_SSR__
const demo = createConsumerDemo(initial?.initial)
const standalone = new URL(location.href).searchParams.has('standalone')
const app = standalone
  ? createApp(StandaloneWidget, { label: 'standalone' })
  : initial
  ? createSSRApp(demo.Root)
  : createApp(demo.Root)
const warnings: string[] = []
app.config.warnHandler = (message) => {
  warnings.push(message)
  console.warn(message)
}
const errors: string[] = []
app.config.errorHandler = (error) => {
  errors.push(String(error))
  console.error(error)
}
const result = standalone
  ? null
  : createDefaultBrowserThemeHost({
      appKey: 'consumer-browser',
      themes: data.themes.map((manifest: unknown) => ({ manifest })),
      defaultThemeId: 'default',
      extensions: data.bundles,
      seedPolicy: { allow: ['brand'] },
      systemPreference: {
        currentMode: () => 'light',
        subscribe: () => () => undefined,
      },
      assetResolver: createThemeAssetResolver({
        exports: {
          async resolve(input) {
            const response = await fetch(
              `/theme-asset?package=${encodeURIComponent(
                input.packageName
              )}&export=${encodeURIComponent(input.exportPath)}`
            )
            return success({ kind: 'css-text', text: await response.text() })
          },
        },
      }),
      ...(initial
        ? {
            hydration: {
              snapshot: initial.output.snapshot,
              stylesheetElements: [
                ...document.querySelectorAll<HTMLElement>(
                  '[data-zx-theme-artifact]'
                ),
              ],
              stylesheetOwnership: 'transferred' as const,
              manualCompletion: true,
              consumers: initial.output.consumers,
              ...(initial.initial.customPortal
                ? { consumerPortalRoots: { aux: document.body } }
                : {}),
              composition: {
                snapshot: initial.output.composition,
                scopeElements: [
                  ...document.querySelectorAll<HTMLElement>('.provider-root'),
                ],
                styleElements: [
                  ...document.querySelectorAll<HTMLElement>(
                    '[data-zx-composition-style]'
                  ),
                ],
                ownership: 'transferred' as const,
              },
            },
          }
        : {}),
    })
const api = (browser.__CONSUMER__ = {
  state: demo.state,
  warnings,
  errors,
  error: null as unknown,
  host: result?.ok ? result.value : null,
  complete: null as unknown,
  async unmount() {
    app.unmount()
    if (result?.ok) await result.value.dispose()
  },
  async settle() {
    await nextTick()
    await nextTick()
  },
})
if (result && !result.ok) api.error = result.diagnostics
else if (standalone) {
  app.mount('#app')
} else {
  const bound = result!.value.bind(app)
  if (!bound.ok) api.error = bound.diagnostics
  else {
    const nodes = [...document.querySelectorAll('[data-zx-consumer]')]
    const styles = [...document.querySelectorAll('style')]
    app.mount('#app')
    await nextTick()
    await nextTick()
    if (initial) {
      const complete = bound.value.completeHydration()
      api.complete = complete
      if (!complete.ok) api.error = complete.diagnostics
      else {
        browser.__CONSUMER_REUSED__ = {
          nodes: nodes.every((node) => node.isConnected),
          styles: styles.every((style) => style.isConnected),
        }
      }
    }
  }
}

/* eslint-disable vue/one-component-per-file -- This harness creates independent owner/portal fixture components. */
import {
  Teleport,
  createApp,
  defineComponent,
  h,
  nextTick,
  ref,
  withDirectives,
} from 'vue'
import {
  themeConsumerDiscoveryKey,
  themeConsumerScopeKey,
} from '@zxio/theme-consumer'
import { useThemePortalBinding } from '@zxio/theme-consumer/vue'
// A second installed tarball, CJS entry. No source module or alias participates.
import { useThemeCssAdapter } from './node_modules/consumer-copy-b/dist/cjs/vue/index.cjs'
import { Widget as Acme } from '@acme/widget/vue'
import { Widget as Panel } from '@example/panel/vue'
import '@acme/widget/style.css'
import '@example/panel/style.css'

const check = (condition: unknown, message: string) => {
  if (!condition) throw new Error(message)
}
const run = async () => {
  const standalone = createApp(
    defineComponent({
      setup: () => () =>
        h('main', [h(Acme, { label: 'a' }), h(Panel, { label: 'b' })]),
    })
  )
  standalone.mount('#app')
  await nextTick()
  check(
    document.querySelectorAll('[data-consumer-status="standalone"]').length ===
      2,
    'both ordinary UIs are standalone'
  )
  const button = document.querySelector('button')!
  button.click()
  await nextTick()
  check(
    button.textContent?.includes('1'),
    'core interaction remains functional'
  )
  standalone.unmount()
  const events: string[] = [],
    listeners = new Set<() => void>()
  const active = ref(true)
  let portal: ReturnType<typeof useThemePortalBinding>
  const abi = { major: 1, minor: 0, capabilities: ['css-target', 'portal'] }
  const port = {
    abi,
    snapshot: () => ({
      phase: 'ready',
      ownerToken: 'host-owner',
      revision: 1,
      diagnostics: [],
    }),
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    preparePortal: () => ({ ok: true, value: null, diagnostics: [] }),
    async acquirePortal() {
      events.push('acquire-portal')
      const target = document.body.appendChild(document.createElement('aside'))
      return {
        ok: true,
        diagnostics: [],
        value: {
          snapshot: () => ({
            state: 'ready',
            target,
            leaseId: 'cross-copy-portal',
            diagnostics: [],
          }),
          subscribe: () => () => undefined,
          release() {
            check(
              !target.querySelector('[data-bound]'),
              'content must release before portal'
            )
            events.push('release-portal')
            target.remove()
          },
        },
      }
    },
    async bindCssTarget(element: HTMLElement, input: any) {
      check(
        input.portalLeaseId === 'cross-copy-portal',
        'cross-copy structural association'
      )
      element.dataset.bound = 'yes'
      events.push('bind-css')
      return {
        ok: true,
        diagnostics: [],
        value: {
          snapshot: () => ({ state: 'ready', diagnostics: [] }),
          subscribe: () => () => undefined,
          release() {
            delete element.dataset.bound
            events.push('release-css')
          },
        },
      }
    },
  }
  const Consumer = defineComponent({
    setup() {
      portal = useThemePortalBinding({ active })
      const root = ref<HTMLElement | null>(null)
      const css = useThemeCssAdapter(
        root,
        { id: 'cross', actualVersion: '1.0.0' },
        { portal }
      )
      return () =>
        active.value && portal.target.value
          ? h(Teleport, { to: portal.target.value }, [
              withDirectives(h('div', { ref: root }, 'cross-copy'), [
                [css.directive],
              ]),
            ])
          : null
    },
  })
  const app = createApp(Consumer)
  app.provide(themeConsumerDiscoveryKey, {
    schema: 'zx.theme-consumer.discovery/1',
    abis: [abi],
  })
  app.provide(themeConsumerScopeKey, port)
  app.mount('#app')
  for (let i = 0; i < 5; i++) await nextTick()
  check(document.querySelector('[data-bound]'), 'portal content mounted')
  active.value = false
  for (let i = 0; i < 5; i++) await nextTick()
  check(
    events.indexOf('release-css') < events.indexOf('release-portal'),
    'release barrier'
  )
  app.unmount()
  await nextTick()
  check(
    listeners.size === 0 && !document.querySelector('aside'),
    'all resources released'
  )
  return {
    status: 'pass',
    copies: ['ESM A portal', 'CJS B CSS'],
    events,
    standalone: 2,
    subscriptionsAfterDispose: listeners.size,
  }
}
run().then(
  (result) => {
    ;(window as any).__PACKED__ = result
  },
  (error) => {
    ;(window as any).__PACKED__ = { status: 'fail', error: String(error) }
    throw error
  }
)
